using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
using System.Xml.Linq;
using System.Windows.Media;
namespace CueStudio {public partial class MainWindow {
 DateTime originalCoolingStamp;DateTime originalProfileStamp;string originalProfilePath;
 static double Num(XElement e,string name,double fallback){double n;return double.TryParse((string)e.Element(name),NumberStyles.Float,CultureInfo.InvariantCulture,out n)?n:fallback;}
 static string Rgb(string raw,string fallback){try{var p=raw.Substring(4).TrimEnd(')').Split(' ');return "#"+string.Concat(p.Select(v=>((int)Math.Round(double.Parse(v,CultureInfo.InvariantCulture)*255)).ToString("X2")));}catch{return fallback;}}
 bool SyncOriginalProfile(){if(Store.EndsWith("test-settings.xml"))return false;try{
  var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"Corsair","CUE5","profiles");var files=Directory.GetFiles(dir,"*.cueprofiledata");if(files.Length!=1)return false;var path=files[0];var stamp=File.GetLastWriteTimeUtc(path);var coolingPath=Path.Combine(dir,"..","cooling","configurations");var coolingStamp=File.Exists(coolingPath)?File.GetLastWriteTimeUtc(coolingPath):DateTime.MinValue;if(path==originalProfilePath&&stamp==originalProfileStamp&&coolingStamp==originalCoolingStamp)return false;var root=XElement.Load(path);
  var types=root.Descendants().Where(e=>e.Element("polymorphic_name")!=null&&e.Element("polymorphic_id")!=null).GroupBy(e=>(uint.Parse((string)e.Element("polymorphic_id"))&0x7fffffff)).ToDictionary(g=>g.Key,g=>(string)g.First().Element("polymorphic_name"));
  Func<XElement,string> type=e=>{uint id;string name;return uint.TryParse((string)e.Element("polymorphic_id"),out id)&&types.TryGetValue(id&0x7fffffff,out name)?name:"";};
  Func<XElement,LightLayer> layer=e=>{var d=e.Element("ptr_wrapper").Element("data");var light=d.Element("lighting");var ld=light.Element("ptr_wrapper").Element("data");string t=type(light);string effect=t=="RainLighting"?"下雨":t=="ColorWaveLighting"?"色波":t=="WatercolorSpectrumLighting"?"水彩光谱":t=="RainbowWaveLighting"?"彩虹波浪":t=="StaticLighting"?"静态颜色":t;var l=new LightLayer{Name=(string)d.Element("base").Element("name"),Effect=effect,Enabled=(string)d.Element("base").Element("enabled")!="false",RandomColor=(string)ld.Element("random")=="true",Speed=Num(ld,"speed",2)*25};var colors=ld.Element("colors");uint color;if(colors!=null&&uint.TryParse((string)colors.Element("first"),out color))l.Color="#"+(color&0xffffff).ToString("X6");if(colors!=null&&uint.TryParse((string)colors.Element("second"),out color))l.Color2="#"+(color&0xffffff).ToString("X6");return l;};
  var devices=root.Element("profile").Element("properties").Elements();var node=devices.FirstOrDefault(e=>(string)e.Element("key")=="LightingNode");
  if(node!=null){var entry=node.Descendants().FirstOrDefault(e=>e.Element("key")!=null&&e.Element("key").Element("deviceId")!=null&&!string.IsNullOrEmpty((string)e.Element("key").Element("deviceId"))&&e.Descendants("channelProperties").Any());if(entry!=null){foreach(var ch in entry.Descendants("channelProperties").Elements()){string channel=(string)ch.Element("key");if(channel!="26"&&channel!="23")continue;var layers=ch.Descendants("layers").Elements().Select(layer).ToList();if(channel=="26")P.Cooler.Layers=layers;else {var original=ch.Descendants("layers").Elements().ToArray();for(int i=0;i<layers.Count;i++){foreach(var key in original[i].Descendants("keys").Elements()){int led;if(int.TryParse(key.Value.Replace("Led_Cmd_Led",""),out led)){if(led>=42&&led<=49)layers[i].Zones.Add(led-42);else if(led>=210&&led<=217)layers[i].Zones.Add(led-210+8);else if(led>=252&&led<=259)layers[i].Zones.Add(led-252+16);}}}P.Cooler.FanLayers=layers;}}}
   var activeScreen=node.Descendants("effect").FirstOrDefault(e=>!string.IsNullOrEmpty(type(e)));if(activeScreen!=null){int si=Array.IndexOf(OriginalCoolingUi.ScreenClasses,type(activeScreen).Replace("ScreenEffectSettings",""));if(si>=0)P.Cooler.ScreenType=screenTypes[si];}
   var dual=node.Descendants().FirstOrDefault(e=>e.Element("polymorphic_id")!=null&&type(e)=="DualBarScreenEffectSettings");if(dual!=null){var d=dual.Element("ptr_wrapper").Element("data");var state=P.Cooler;var colors=d.Element("mainColors").Elements().ToArray();state.ScreenColor1=Rgb(colors[0].Value,state.ScreenColor1);state.ScreenColor2=Rgb(colors[1].Value,state.ScreenColor2);state.ScreenBackground=Rgb((string)d.Element("backgroundColor"),state.ScreenBackground);state.ScreenLabel=Rgb((string)d.Element("labelColor"),state.ScreenLabel);state.MinTemp=Num(d,"minValue1",20);state.MaxTemp=Num(d,"maxValue1",60);state.MinTemp2=Num(d,"minValue2",20);state.MaxTemp2=Num(d,"maxValue2",60);state.Fps=Num(d.Element("base"),"fps",30);state.Sensor1=ScreenSensorName((string)d.Element("sensorId1"));state.Sensor2=ScreenSensorName((string)d.Element("sensorId2"));}}
  var dram=devices.FirstOrDefault(e=>(string)e.Element("key")=="DRAM");if(dram!=null){var entry=dram.Descendants().FirstOrDefault(e=>e.Element("key")!=null&&(string)e.Element("key").Element("hidCaps")=="DramSoftware"&&(string)e.Element("key").Element("deviceLightingType")=="Dominator");if(entry!=null)P.Memory.Layers=entry.Descendants("layers").Elements().Select(layer).ToList();}
  var coolingRoot=new XElement("combined");if(File.Exists(coolingPath)){var library=XElement.Load(coolingPath);var storage=library.Descendants("storages").Elements().FirstOrDefault(e=>(string)e.Element("key")=="430a201134895aaab9f09f061091005f");if(storage!=null)coolingRoot.Add(new XElement(storage.Element("value").Element("software")));}coolingRoot.Add(new XElement(root));ReadCoolingProfile(coolingRoot);originalCoolingStamp=coolingStamp;originalProfileStamp=stamp;originalProfilePath=path;Save();return true;
 }catch(Exception ex){System.Diagnostics.Debug.WriteLine(ex);return false;}}
 void ReadCoolingProfile(XElement root){var state=P.Cooler;var configs=new Dictionary<string,CurveState>();var refs=new Dictionary<string,string>();foreach(var d in root.Descendants("data").Where(d=>d.Element("customModePoints")!=null&&d.Element("base")!=null)){string id=(string)d.Element("base").Element("id"),name=(string)d.Element("base").Element("name");if(string.IsNullOrEmpty(id))continue;name=name=="Balanced"?"均衡":name=="Quiet"?"静音":name=="Extreme"?"极限":name=="Zero RPM"?"零 RPM":name=="Variable Speed"?"变速":name;var pts=d.Element("customModePoints");var model=d.Elements("coolerComponentsCurves").Elements().FirstOrDefault(e=>(string)e.Element("key")=="h100iLcd");if(model!=null&&(string)d.Element("base").Element("predefined")=="true")pts=model.Element("value").Element("customModePoints");var curve=new CurveState{Name=name,OriginalId=id,Sensor=((string)d.Element("sensorId")??"").Contains("TemperaturePackage")?"CPU 温度":"H100i ELITE LCD 冷却液温度",Mode=(string)d.Element("fanMode")=="FixedRpm"?"固定 RPM":(string)d.Element("fanMode")=="FixedPercentage"?"固定百分比":"自定义曲线",FixedPercent=Num(d,"fixedPercents",50),FixedRpm=Num(d,"fixedRpm",1200)};foreach(var pt in pts.Elements().Where(e=>(string)e.Element("enabled")!="false")){curve.Temperatures.Add(Num(pt,"sensorValue",0));curve.Values.Add(Num(pt,"rpmPercents",0));}if(curve.Values.Count<2)continue;configs[id]=curve;var ptr=d.Parent;uint pid;if(uint.TryParse((string)ptr.Element("id"),out pid))refs[(pid&0x7fffffff).ToString()]=id;var old=state.Curves.Find(c=>c.OriginalId==id||c.Name==name);if(old==null){if(Option("hiddenCooling:"+id)!="1")state.Curves.Add(curve);}else if(!old.Edited){state.Curves.Remove(old);state.Curves.Add(curve);}}
 state.Curves.RemoveAll(c=>!string.IsNullOrEmpty(c.OriginalId)&&!configs.ContainsKey(c.OriginalId)&&!c.Edited);foreach(var a in root.Descendants("assignments").Elements()){string key=(string)a.Element("key")??"";if(!key.Contains("430a201134895aaab9f09f061091005f"))continue;var v=a.Element("value");if(v==null)continue;string id=(string)v.Element("assignmentConfigId");CurveState curve;if(id==null||!configs.TryGetValue(id,out curve)){var def=v.Element("defaultConfig");uint pid;string mapped;if(def==null||!uint.TryParse((string)def.Element("ptr_wrapper").Element("id"),out pid)||!refs.TryGetValue((pid&0x7fffffff).ToString(),out mapped)||!configs.TryGetValue(mapped,out curve))continue;}string channel=key.Contains("senstype<pump>")?"泵":key.Contains("senstype<fan>")&&key.Contains("sensindex<4>")?"风扇 #5":key.Contains("senstype<fan>")&&key.Contains("sensindex<5>")?"风扇 #6":null;if(channel==null)continue;originalCoolingBindings[channel]=curve.Name;if(state.CoolingBindingsEdited)continue;if(channel=="泵")state.Pump=curve.Name;else if(channel=="风扇 #5")state.Fan=curve.Name;else state.Fan6=curve.Name;}
 }
 string ScreenSensorName(string id){if(id.Contains("430a201134895aaab9f09f061091005f"))return "H100i ELITE LCD 冷却液温度";if(id.Contains("TemperaturePackage"))return "AMD Ryzen 9 9900X 包";if(id.Contains("NVIDIA")||id.Contains("10de"))return "NVIDIA GeForce RTX 3090 温度 #1";return "未识别的原版测点";}
 Reading LcdReading(string sensor){if(sensor=="H100i ELITE LCD 冷却液温度")return Telemetry.Resolve("H100i ELITE LCD","冷却液温度","°C");if(sensor=="AMD Ryzen 9 9900X 包")return Telemetry.Resolve("AMD Ryzen 9 9900X","包","°C");if(sensor=="NVIDIA GeForce RTX 3090 温度"||sensor=="NVIDIA GeForce RTX 3090 温度 #1")return Telemetry.Resolve("NVIDIA GeForce RTX 3090","温度 #1","°C");return new Reading{Name=sensor,Unit="°C"};}
}}
